function snapshot_ToyLibRef()
% Self-contained snapshot generated by simulink-snapshot-edit.
% Run once to rebuild ToyLibRef.slx exactly (blocks/params/positions/routing).
% Local-edit workflow: edit only the lines of the block you need.
  if bdIsLoaded('ToyLibRef'), close_system('ToyLibRef', 0); end
  new_system('ToyLibRef');
  m = 'ToyLibRef';
  if ~bdIsLoaded('ToyLib'), load_system(fullfile(fileparts(mfilename('fullpath')), '..\lib\blocks', 'ToyLib.slx')); end

  % ---- solver / config / model params ----

  % ---- callbacks ----

  % ---- Model Workspace variables ----

  % ---- blocks (positions & full parameters preserved) ----
  add_block('simulink/Sources/Constant', [m '/c1'], 'Position', [40 40 80 70], 'Value', '1', 'VectorParams1D', 'on', 'OutMin', '[]', 'OutMax', '[]', 'OutDataTypeStr', 'Inherit: Inherit from ''Constant value''', 'LockScale', 'off', 'SampleTime', 'inf', 'FramePeriod', 'inf');
  add_block('ToyLib/ToyGain', [m '/tg'], 'Position', [140 40 200 80], 'ShowPortLabels', 'FromPortIcon', 'SystemSampleTime', '-1');
  add_block('ToyLib/ToyInner', [m '/ti'], 'Position', [260 40 320 80], 'ShowPortLabels', 'FromPortIcon', 'SystemSampleTime', '-1');
  add_block('ToyLib/ToyLimited', [m '/tl'], 'Position', [380 40 440 80], 'UpperLimit', '1');
  add_block('ToyLib/ToyMasked', [m '/tm'], 'Position', [500 40 560 80], 'Kp', '5');
  add_block('simulink/Sinks/Out1', [m '/y1'], 'Position', [640 40 690 60], 'Port', '1');
  try, set_param(m, 'SimulationCommand', 'update'); catch, end

  % ---- lines ----
  lnH = add_line(m, 'tm/1', 'y1/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [565 60;625 50;635 50]); catch, end
  lnH = add_line(m, 'tl/1', 'tm/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [445 60;495 60]); catch, end
  lnH = add_line(m, 'ti/1', 'tl/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [325 60;375 60]); catch, end
  lnH = add_line(m, 'tg/1', 'ti/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [205 60;255 60]); catch, end
  lnH = add_line(m, 'c1/1', 'tg/1', 'autorouting', 'off');
  try, set_param(lnH, 'Points', [85 55;125 60;135 60]); catch, end

  % ---- annotations (top level) ----

  snpDir = fileparts(mfilename('fullpath'));
  snpOut = fullfile(snpDir, '..\models');
  try, bdclose('ToyLibRef_tmp_save'); catch, end
  if ~isfolder(snpOut), mkdir(snpOut); end
  if isfile(fullfile(snpOut, 'ToyLibRef_tmp_save.slx')), delete(fullfile(snpOut, 'ToyLibRef_tmp_save.slx')); end
  save_system(m, fullfile(snpOut, 'ToyLibRef_tmp_save.slx'));
  close_system(m, 0);
  movefile(fullfile(snpOut, 'ToyLibRef_tmp_save.slx'), fullfile(snpOut, 'ToyLibRef.slx'), 'f');
end

